.regras-form-botoes { display: flex; flex-wrap: wrap; gap: var(--esp-2); }
@media (min-width: 640px) { .regras-form { grid-template-columns: repeat(2, minmax(0, 1fr)); } }
@media (min-width: 1024px) { .regras-form { grid-template-columns: repeat(3, minmax(0, 1fr)); } }

.regras-lista { margin: 0; padding: 0; list-style: none; }
.regras-lista > li + li { border-top: 1px solid var(--cor-borda); }
.regras-item-edicao { padding: var(--esp-3) 0; }
.regras-item { display: grid; gap: var(--esp-2); padding: var(--esp-3) 0; }
.regras-item-inativa { opacity: 0.7; }
.regras-item-corpo { display: flex; flex-wrap: wrap; align-items: flex-start; justify-content: space-between; gap: var(--esp-2); }
.regras-item-texto { min-width: 0; flex: 1 1 14rem; overflow-wrap: anywhere; }
.regras-item-texto p { margin: 0; }
.regras-item-titulo { font-weight: 500; color: var(--cor-texto); }
.regras-item-posicao { margin-right: var(--esp-2); color: var(--cor-texto-suave); }
.regras-item-detalhe { font-size: var(--texto-xs); color: var(--cor-texto-suave); }
.regras-item-previa { font-size: var(--texto-xs); font-weight: 500; color: var(--cor-texto-suave); }
.regras-item-acoes { display: flex; flex-wrap: wrap; align-items: center; gap: var(--esp-2); }
